// KI upscaler for the Vulkan renderer.
//
// The game window's image (X server resolution) is run through a small convolutional
// network as a chain of compute dispatches on half-float storage images. The last image
// holds the 4 sub-pixels of a 2x luma upscale per texel; ki_window.frag then draws the
// window at screen size from it (luma detail on top of the bilinear colour upscale).
//
// Shaders are generated by ki/tools/gen_vulkan.py into ki/ki_spirv.h.
#include "VulkanRendererContext.h"
#include "window_vert.h"
#include "ki/ki_spirv.h"

#include <algorithm>
#include <stdexcept>

static constexpr VkFormat KI_FORMAT = VK_FORMAT_R16G16B16A16_SFLOAT;
static constexpr int KI_MAX_BINDS = 3;

bool VulkanRendererContext::kiInit() {
    kiCreateComputePipelines = (PFN_vkCreateComputePipelines)vk_.GetDeviceProcAddr(device, "vkCreateComputePipelines");
    kiCmdDispatch = (PFN_vkCmdDispatch)vk_.GetDeviceProcAddr(device, "vkCmdDispatch");
    if (!kiCreateComputePipelines || !kiCmdDispatch) {
        RLOG_E("KI: compute entry points missing");
        return false;
    }

    VkFormatProperties fp{};
    vk_.GetPhysicalDeviceFormatProperties(physicalDevice, KI_FORMAT, &fp);
    if (!(fp.optimalTilingFeatures & VK_FORMAT_FEATURE_STORAGE_IMAGE_BIT)) {
        RLOG_E("KI: RGBA16F storage images not supported");
        return false;
    }

    try {
        // Compute: bindings 0..2 sampled inputs, 3 storage output.
        VkDescriptorSetLayoutBinding b[KI_MAX_BINDS + 1]{};
        for (int i = 0; i < KI_MAX_BINDS; i++) {
            b[i].binding = i; b[i].descriptorCount = 1;
            b[i].descriptorType = VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER;
            b[i].stageFlags = VK_SHADER_STAGE_COMPUTE_BIT;
        }
        b[KI_MAX_BINDS].binding = KI_MAX_BINDS; b[KI_MAX_BINDS].descriptorCount = 1;
        b[KI_MAX_BINDS].descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_IMAGE;
        b[KI_MAX_BINDS].stageFlags = VK_SHADER_STAGE_COMPUTE_BIT;
        VkDescriptorSetLayoutCreateInfo dl{}; dl.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO;
        dl.bindingCount = KI_MAX_BINDS + 1; dl.pBindings = b;
        if (vk_.CreateDescriptorSetLayout(device, &dl, nullptr, &kiDsLayout) != VK_SUCCESS) throw std::runtime_error("ki dsl");

        VkPushConstantRange pr{}; pr.stageFlags = VK_SHADER_STAGE_COMPUTE_BIT; pr.size = 2 * sizeof(int32_t);
        VkPipelineLayoutCreateInfo pl{}; pl.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
        pl.setLayoutCount = 1; pl.pSetLayouts = &kiDsLayout; pl.pushConstantRangeCount = 1; pl.pPushConstantRanges = &pr;
        if (vk_.CreatePipelineLayout(device, &pl, nullptr, &kiPipeLayout) != VK_SUCCESS) throw std::runtime_error("ki pl");

        kiPipelines.assign(KI_PASS_COUNT, VK_NULL_HANDLE);
        for (int p = 0; p < KI_PASS_COUNT; p++) {
            VkShaderModule m = makeShader(KI_PASSES[p].code, KI_PASSES[p].size);
            VkComputePipelineCreateInfo ci{}; ci.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
            ci.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
            ci.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT; ci.stage.module = m; ci.stage.pName = "main";
            ci.layout = kiPipeLayout;
            VkResult r = kiCreateComputePipelines(device, VK_NULL_HANDLE, 1, &ci, nullptr, &kiPipelines[p]);
            vk_.DestroyShaderModule(device, m, nullptr);
            if (r != VK_SUCCESS) throw std::runtime_error("ki compute pipeline");
        }

        // Output: set 1 = network sub-pixels, sampled with texelFetch.
        VkDescriptorSetLayoutBinding ob{}; ob.binding = 0; ob.descriptorCount = 1;
        ob.descriptorType = VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER; ob.stageFlags = VK_SHADER_STAGE_FRAGMENT_BIT;
        VkDescriptorSetLayoutCreateInfo odl{}; odl.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO;
        odl.bindingCount = 1; odl.pBindings = &ob;
        if (vk_.CreateDescriptorSetLayout(device, &odl, nullptr, &kiOutDsLayout) != VK_SUCCESS) throw std::runtime_error("ki out dsl");

        VkDescriptorSetLayout outSets[2] = {dsLayout, kiOutDsLayout};
        VkPushConstantRange opr{}; opr.stageFlags = VK_SHADER_STAGE_VERTEX_BIT | VK_SHADER_STAGE_FRAGMENT_BIT;
        opr.size = sizeof(WindowPushConstants);
        VkPipelineLayoutCreateInfo opl{}; opl.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
        opl.setLayoutCount = 2; opl.pSetLayouts = outSets; opl.pushConstantRangeCount = 1; opl.pPushConstantRanges = &opr;
        if (vk_.CreatePipelineLayout(device, &opl, nullptr, &kiOutPipeLayout) != VK_SUCCESS) throw std::runtime_error("ki out pl");

        VkShaderModule vert = makeShader(window_vert_code, sizeof(window_vert_code));
        VkShaderModule frag = makeShader(ki_window_frag_spv, sizeof(ki_window_frag_spv));
        VkPipelineShaderStageCreateInfo st[2]{};
        st[0].sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO; st[0].stage = VK_SHADER_STAGE_VERTEX_BIT; st[0].module = vert; st[0].pName = "main";
        st[1].sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO; st[1].stage = VK_SHADER_STAGE_FRAGMENT_BIT; st[1].module = frag; st[1].pName = "main";
        VkPipelineVertexInputStateCreateInfo vi{}; vi.sType = VK_STRUCTURE_TYPE_PIPELINE_VERTEX_INPUT_STATE_CREATE_INFO;
        VkPipelineInputAssemblyStateCreateInfo ia{}; ia.sType = VK_STRUCTURE_TYPE_PIPELINE_INPUT_ASSEMBLY_STATE_CREATE_INFO; ia.topology = VK_PRIMITIVE_TOPOLOGY_TRIANGLE_STRIP;
        VkDynamicState dyn[] = {VK_DYNAMIC_STATE_VIEWPORT, VK_DYNAMIC_STATE_SCISSOR};
        VkPipelineDynamicStateCreateInfo ds{}; ds.sType = VK_STRUCTURE_TYPE_PIPELINE_DYNAMIC_STATE_CREATE_INFO; ds.dynamicStateCount = 2; ds.pDynamicStates = dyn;
        VkPipelineViewportStateCreateInfo vp{}; vp.sType = VK_STRUCTURE_TYPE_PIPELINE_VIEWPORT_STATE_CREATE_INFO; vp.viewportCount = 1; vp.scissorCount = 1;
        VkPipelineRasterizationStateCreateInfo rs{}; rs.sType = VK_STRUCTURE_TYPE_PIPELINE_RASTERIZATION_STATE_CREATE_INFO; rs.polygonMode = VK_POLYGON_MODE_FILL; rs.lineWidth = 1.f; rs.cullMode = VK_CULL_MODE_NONE; rs.frontFace = VK_FRONT_FACE_COUNTER_CLOCKWISE;
        VkPipelineMultisampleStateCreateInfo msi{}; msi.sType = VK_STRUCTURE_TYPE_PIPELINE_MULTISAMPLE_STATE_CREATE_INFO; msi.rasterizationSamples = VK_SAMPLE_COUNT_1_BIT;
        VkPipelineColorBlendAttachmentState ba{}; ba.colorWriteMask = 0xF; ba.blendEnable = VK_FALSE;
        VkPipelineColorBlendStateCreateInfo cb{}; cb.sType = VK_STRUCTURE_TYPE_PIPELINE_COLOR_BLEND_STATE_CREATE_INFO; cb.attachmentCount = 1; cb.pAttachments = &ba;
        VkGraphicsPipelineCreateInfo gp{}; gp.sType = VK_STRUCTURE_TYPE_GRAPHICS_PIPELINE_CREATE_INFO;
        gp.stageCount = 2; gp.pStages = st; gp.pVertexInputState = &vi; gp.pInputAssemblyState = &ia;
        gp.pViewportState = &vp; gp.pRasterizationState = &rs; gp.pMultisampleState = &msi;
        gp.pColorBlendState = &cb; gp.pDynamicState = &ds; gp.layout = kiOutPipeLayout; gp.renderPass = renderPass; gp.subpass = 0;
        VkResult gr = vk_.CreateGraphicsPipelines(device, VK_NULL_HANDLE, 1, &gp, nullptr, &kiOutPipeline);
        vk_.DestroyShaderModule(device, frag, nullptr);
        vk_.DestroyShaderModule(device, vert, nullptr);
        if (gr != VK_SUCCESS) throw std::runtime_error("ki out pipeline");

        VkDescriptorPoolSize ps[2] = {
            {VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER, (uint32_t)(MAX_FRAMES_IN_FLIGHT * (KI_PASS_COUNT * KI_MAX_BINDS + 1))},
            {VK_DESCRIPTOR_TYPE_STORAGE_IMAGE, (uint32_t)(MAX_FRAMES_IN_FLIGHT * KI_PASS_COUNT)},
        };
        VkDescriptorPoolCreateInfo pci{}; pci.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO;
        pci.poolSizeCount = 2; pci.pPoolSizes = ps; pci.maxSets = MAX_FRAMES_IN_FLIGHT * (KI_PASS_COUNT + 1);
        if (vk_.CreateDescriptorPool(device, &pci, nullptr, &kiPool) != VK_SUCCESS) throw std::runtime_error("ki pool");

        kiSets.assign(MAX_FRAMES_IN_FLIGHT * KI_PASS_COUNT, VK_NULL_HANDLE);
        std::vector<VkDescriptorSetLayout> layouts(kiSets.size(), kiDsLayout);
        VkDescriptorSetAllocateInfo ai{}; ai.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO;
        ai.descriptorPool = kiPool; ai.descriptorSetCount = (uint32_t)layouts.size(); ai.pSetLayouts = layouts.data();
        if (vk_.AllocateDescriptorSets(device, &ai, kiSets.data()) != VK_SUCCESS) throw std::runtime_error("ki sets");
        std::vector<VkDescriptorSetLayout> outLayouts(MAX_FRAMES_IN_FLIGHT, kiOutDsLayout);
        ai.descriptorSetCount = MAX_FRAMES_IN_FLIGHT; ai.pSetLayouts = outLayouts.data();
        if (vk_.AllocateDescriptorSets(device, &ai, kiOutSets) != VK_SUCCESS) throw std::runtime_error("ki out sets");

        VkSamplerCreateInfo sci{}; sci.sType = VK_STRUCTURE_TYPE_SAMPLER_CREATE_INFO;
        sci.magFilter = sci.minFilter = VK_FILTER_NEAREST;
        sci.addressModeU = sci.addressModeV = sci.addressModeW = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
        sci.mipmapMode = VK_SAMPLER_MIPMAP_MODE_NEAREST; sci.maxLod = 0.f;
        if (vk_.CreateSampler(device, &sci, nullptr, &kiNearest) != VK_SUCCESS) throw std::runtime_error("ki sampler");
    } catch (const std::exception& e) {
        RLOG_E("KI: init failed: %s", e.what());
        kiDestroy();
        return false;
    }
    kiReady = true;
    RLOG("KI: initialised %d passes", KI_PASS_COUNT);
    return true;
}

void VulkanRendererContext::kiDestroyImages() {
    for (auto& im : kiImages) {
        if (im.view != VK_NULL_HANDLE) vk_.DestroyImageView(device, im.view, nullptr);
        if (im.img != VK_NULL_HANDLE) vk_.DestroyImage(device, im.img, nullptr);
        if (im.mem != VK_NULL_HANDLE) vk_.FreeMemory(device, im.mem, nullptr);
    }
    kiImages.clear();
    kiW = kiH = 0;
}

bool VulkanRendererContext::kiEnsureImages(int w, int h) {
    if (w == kiW && h == kiH && (int)kiImages.size() == KI_IMAGE_COUNT) return true;
    if (!kiImages.empty()) {
        vk_.DeviceWaitIdle(device);  // size changes are rare (resolution switch)
        kiDestroyImages();
    }
    kiImages.resize(KI_IMAGE_COUNT);
    for (auto& im : kiImages) {
        VkImageCreateInfo ii{}; ii.sType = VK_STRUCTURE_TYPE_IMAGE_CREATE_INFO;
        ii.imageType = VK_IMAGE_TYPE_2D; ii.format = KI_FORMAT; ii.extent = {(uint32_t)w, (uint32_t)h, 1};
        ii.mipLevels = 1; ii.arrayLayers = 1; ii.samples = VK_SAMPLE_COUNT_1_BIT; ii.tiling = VK_IMAGE_TILING_OPTIMAL;
        ii.usage = VK_IMAGE_USAGE_STORAGE_BIT | VK_IMAGE_USAGE_SAMPLED_BIT;
        ii.sharingMode = VK_SHARING_MODE_EXCLUSIVE; ii.initialLayout = VK_IMAGE_LAYOUT_UNDEFINED;
        if (vk_.CreateImage(device, &ii, nullptr, &im.img) != VK_SUCCESS) { kiDestroyImages(); return false; }
        VkMemoryRequirements req; vk_.GetImageMemoryRequirements(device, im.img, &req);
        VkMemoryAllocateInfo mai{}; mai.sType = VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO;
        mai.allocationSize = req.size;
        try { mai.memoryTypeIndex = findMemType(req.memoryTypeBits, VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT); }
        catch (...) { kiDestroyImages(); return false; }
        if (vk_.AllocateMemory(device, &mai, nullptr, &im.mem) != VK_SUCCESS ||
            vk_.BindImageMemory(device, im.img, im.mem, 0) != VK_SUCCESS) { kiDestroyImages(); return false; }
        VkImageViewCreateInfo vi{}; vi.sType = VK_STRUCTURE_TYPE_IMAGE_VIEW_CREATE_INFO;
        vi.image = im.img; vi.viewType = VK_IMAGE_VIEW_TYPE_2D; vi.format = KI_FORMAT;
        vi.subresourceRange = {VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, 1};
        if (vk_.CreateImageView(device, &vi, nullptr, &im.view) != VK_SUCCESS) { kiDestroyImages(); return false; }
    }
    kiW = w; kiH = h;
    kiImagesNeedInit = true;
    RLOG("KI: images %dx%d", w, h);
    return true;
}

bool VulkanRendererContext::kiRecord(VkCommandBuffer cb, VkImageView src, int w, int h, uint32_t frame) {
    if (kiFailed || src == VK_NULL_HANDLE || w <= 0 || h <= 0) return false;
    if (!kiReady && !kiInit()) { kiFailed = true; return false; }
    if (!kiEnsureImages(w, h)) { RLOG_E("KI: image allocation failed"); kiFailed = true; return false; }

    // Descriptors for this frame-in-flight (its previous use has completed: fence waited).
    std::vector<VkDescriptorImageInfo> infos((size_t)KI_PASS_COUNT * (KI_MAX_BINDS + 1) + 1);
    std::vector<VkWriteDescriptorSet> writes;
    writes.reserve(infos.size());
    size_t n = 0;
    for (int p = 0; p < KI_PASS_COUNT; p++) {
        VkDescriptorSet set = kiSets[frame * KI_PASS_COUNT + p];
        for (int b = 0; b <= KI_MAX_BINDS; b++) {
            VkDescriptorImageInfo& ii = infos[n++];
            VkWriteDescriptorSet wr{}; wr.sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET;
            wr.dstSet = set; wr.dstBinding = b; wr.descriptorCount = 1; wr.pImageInfo = &ii;
            if (b == KI_MAX_BINDS) {
                ii.imageView = kiImages[KI_PASSES[p].save].view; ii.imageLayout = VK_IMAGE_LAYOUT_GENERAL;
                wr.descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_IMAGE;
            } else {
                int bi = KI_PASSES[p].binds[b];
                ii.sampler = kiNearest;
                if (bi >= 0) { ii.imageView = kiImages[bi].view; ii.imageLayout = VK_IMAGE_LAYOUT_GENERAL; }
                else { ii.imageView = src; ii.imageLayout = VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL; }  // LUMA / unused
                wr.descriptorType = VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER;
            }
            writes.push_back(wr);
        }
    }
    {
        VkDescriptorImageInfo& ii = infos[n++];
        ii.sampler = kiNearest; ii.imageView = kiImages[KI_OUTPUT_IMAGE].view; ii.imageLayout = VK_IMAGE_LAYOUT_GENERAL;
        VkWriteDescriptorSet wr{}; wr.sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET;
        wr.dstSet = kiOutSets[frame]; wr.dstBinding = 0; wr.descriptorCount = 1; wr.pImageInfo = &ii;
        wr.descriptorType = VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER;
        writes.push_back(wr);
    }
    vk_.UpdateDescriptorSets(device, (uint32_t)writes.size(), writes.data(), 0, nullptr);

    if (kiImagesNeedInit) {
        std::vector<VkImageMemoryBarrier> bs(kiImages.size());
        for (size_t i = 0; i < kiImages.size(); i++) {
            VkImageMemoryBarrier& b = bs[i]; b = {}; b.sType = VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER;
            b.oldLayout = VK_IMAGE_LAYOUT_UNDEFINED; b.newLayout = VK_IMAGE_LAYOUT_GENERAL;
            b.srcQueueFamilyIndex = b.dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
            b.image = kiImages[i].img; b.subresourceRange = {VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, 1};
            b.srcAccessMask = 0; b.dstAccessMask = VK_ACCESS_SHADER_READ_BIT | VK_ACCESS_SHADER_WRITE_BIT;
        }
        vk_.CmdPipelineBarrier(cb, VK_PIPELINE_STAGE_TOP_OF_PIPE_BIT, VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,
            0, 0, nullptr, 0, nullptr, (uint32_t)bs.size(), bs.data());
        kiImagesNeedInit = false;
    } else {
        // The previous frame's fragment/compute reads of these images must finish before we overwrite them.
        VkMemoryBarrier mb{}; mb.sType = VK_STRUCTURE_TYPE_MEMORY_BARRIER;
        mb.srcAccessMask = VK_ACCESS_SHADER_READ_BIT | VK_ACCESS_SHADER_WRITE_BIT;
        mb.dstAccessMask = VK_ACCESS_SHADER_READ_BIT | VK_ACCESS_SHADER_WRITE_BIT;
        vk_.CmdPipelineBarrier(cb, VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT | VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,
            VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT, 0, 1, &mb, 0, nullptr, 0, nullptr);
    }

    int32_t size[2] = {w, h};
    uint32_t gx = (uint32_t)((w + 7) / 8), gy = (uint32_t)((h + 7) / 8);
    for (int p = 0; p < KI_PASS_COUNT; p++) {
        vk_.CmdBindPipeline(cb, VK_PIPELINE_BIND_POINT_COMPUTE, kiPipelines[p]);
        VkDescriptorSet set = kiSets[frame * KI_PASS_COUNT + p];
        vk_.CmdBindDescriptorSets(cb, VK_PIPELINE_BIND_POINT_COMPUTE, kiPipeLayout, 0, 1, &set, 0, nullptr);
        vk_.CmdPushConstants(cb, kiPipeLayout, VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(size), size);
        kiCmdDispatch(cb, gx, gy, 1);
        VkMemoryBarrier mb{}; mb.sType = VK_STRUCTURE_TYPE_MEMORY_BARRIER;
        mb.srcAccessMask = VK_ACCESS_SHADER_WRITE_BIT; mb.dstAccessMask = VK_ACCESS_SHADER_READ_BIT;
        VkPipelineStageFlags dst = (p == KI_PASS_COUNT - 1) ? VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT : VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT;
        vk_.CmdPipelineBarrier(cb, VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT, dst, 0, 1, &mb, 0, nullptr, 0, nullptr);
    }
    return true;
}

void VulkanRendererContext::kiDestroy() {
    kiDestroyImages();
    for (auto p : kiPipelines) if (p != VK_NULL_HANDLE) vk_.DestroyPipeline(device, p, nullptr);
    kiPipelines.clear();
    if (kiOutPipeline != VK_NULL_HANDLE) { vk_.DestroyPipeline(device, kiOutPipeline, nullptr); kiOutPipeline = VK_NULL_HANDLE; }
    if (kiPool != VK_NULL_HANDLE) { vk_.DestroyDescriptorPool(device, kiPool, nullptr); kiPool = VK_NULL_HANDLE; }
    kiSets.clear();
    for (auto& s : kiOutSets) s = VK_NULL_HANDLE;
    if (kiPipeLayout != VK_NULL_HANDLE) { vk_.DestroyPipelineLayout(device, kiPipeLayout, nullptr); kiPipeLayout = VK_NULL_HANDLE; }
    if (kiOutPipeLayout != VK_NULL_HANDLE) { vk_.DestroyPipelineLayout(device, kiOutPipeLayout, nullptr); kiOutPipeLayout = VK_NULL_HANDLE; }
    if (kiDsLayout != VK_NULL_HANDLE) { vk_.DestroyDescriptorSetLayout(device, kiDsLayout, nullptr); kiDsLayout = VK_NULL_HANDLE; }
    if (kiOutDsLayout != VK_NULL_HANDLE) { vk_.DestroyDescriptorSetLayout(device, kiOutDsLayout, nullptr); kiOutDsLayout = VK_NULL_HANDLE; }
    if (kiNearest != VK_NULL_HANDLE) { vk_.DestroySampler(device, kiNearest, nullptr); kiNearest = VK_NULL_HANDLE; }
    kiReady = false;
}
